def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    q = int(data[0])
    index = 1
    a = []

    for _ in range(q):
        task_type = int(data[index])
        index += 1

        if task_type == 1:
            u_i = int(data[index])
            index += 1
            a.append(u_i)
        elif task_type == 2:
            x_i = int(data[index])
            k_i = int(data[index + 1])
            s_i = int(data[index + 2])
            index += 3

            max_xor = -1
            best_v = -1

            for v in a:
                if gcd(x_i, v) % k_i == 0 and x_i + v <= s_i:
                    if x_i ^ v > max_xor:
                        max_xor = x_i ^ v
                        best_v = v

            print(best_v)

if __name__ == "__main__":
    main()
